```python
def find_difference(numbers):
    first_even = None
    first_odd = None

    for number in numbers:
        if first_even is None and number % 2 == 0:
            first_even = number
        if first_odd is None and number % 2 != 0:
            first_odd = number
        if first_even is not None and first_odd is not None:
            break

    if first_even is not None and first_odd is not None:
        return first_even - first_odd
    else:
        return None

# Example usage:
